begin;
create temporary table finding_test_ids(fid uuid,rid uuid);grant select,insert on finding_test_ids to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
do $$
declare p uuid:='11111111-1111-4111-8111-111111111111';rev jsonb;run jsonb;ret jsonb;f jsonb;fid uuid;rid uuid;passed uuid;again uuid;token uuid:='aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee';ev jsonb:='[{"id":"proof","kind":"screenshot","sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","availability":"local","capturedAt":"2026-10-14T00:00:00Z"}]';failed jsonb:='[{"checkId":"one","criterionId":"one","verdict":"failed","observed":"Unexpected","reason":"Independent","evidenceIds":["proof"],"checkedAt":"2026-10-14T00:00:00Z"}]';good jsonb:='[{"checkId":"one","criterionId":"one","verdict":"passed","observed":"Ready","reason":"Independent","evidenceIds":["proof"],"checkedAt":"2026-10-14T00:00:00Z"}]';
begin
 rev:=public.save_dynamic_revision(p,auth.uid(),'{"name":"Finding","goal":"Read","targetUrl":"http://localhost:3000/","maxSteps":2,"context":null,"checks":[{"id":"one","criterionId":"one","description":"Ready","kind":"visible_text","expected":"Ready","required":true}]}');
 ret:=public.start_dynamic_run(p,auth.uid(),(rev->>'id')::uuid,'finding-fail');rid:=(ret->'run'->>'id')::uuid;perform public.claim_dynamic_run(p,rid,'worker',token,'finding-session');run:=public.transition_dynamic_run(p,rid,'running',jsonb_build_object('state','completed','verdict','failed','leaseToken',token,'checks',failed,'evidence',ev));
 ret:=public.collect_dynamic_findings(p,rid);if jsonb_array_length(ret)<>1 then raise exception 'Missing failed candidate';end if;f:=ret->0;fid:=(f->>'id')::uuid;
 if f->>'verification'<>'unreviewed' or f->'severity'<>'null'::jsonb or f->'priority'<>'null'::jsonb or f->>'observationCount'<>'1' then raise exception 'Candidate invented triage or confirmation';end if;
 if public.collect_dynamic_findings(p,rid) is distinct from ret then raise exception 'Replay changed candidate';end if;
 if (select count(*) from public.dynamic_finding_observations where finding_id=fid)<>1 then raise exception 'Duplicate observation';end if;
 begin perform public.review_dynamic_finding(p,fid,jsonb_build_object('version',1,'decision','confirmed','note','Confirmed'));raise exception 'Missing triage accepted';exception when raise_exception then if sqlerrm='Missing triage accepted' then raise;end if;end;
 ret:=public.start_dynamic_run(p,auth.uid(),(rev->>'id')::uuid,'finding-missing-proof');again:=(ret->'run'->>'id')::uuid;perform public.claim_dynamic_run(p,again,'worker',token,'missing-proof');perform public.transition_dynamic_run(p,again,'running',jsonb_build_object('state','completed','verdict','failed','leaseToken',token,'checks','[{"checkId":"one","criterionId":"one","verdict":"failed"}]'::jsonb,'evidence',ev));
 if public.collect_dynamic_findings(p,again)<>'[]'::jsonb then raise exception 'Missing proof became a candidate';end if;
 ret:=public.start_dynamic_run(p,auth.uid(),(rev->>'id')::uuid,'finding-missing-verdict');again:=(ret->'run'->>'id')::uuid;perform public.claim_dynamic_run(p,again,'worker',token,'missing-verdict');perform public.transition_dynamic_run(p,again,'running',jsonb_build_object('state','completed','verdict','failed','leaseToken',token,'checks','[{"checkId":"one","criterionId":"one","evidenceIds":["proof"]}]'::jsonb,'evidence',ev));
 if public.collect_dynamic_findings(p,again)<>'[]'::jsonb then raise exception 'Missing failed verdict became a candidate';end if;
 begin perform public.review_dynamic_finding(p,fid,'[]'::jsonb);raise exception 'Scalar decision accepted';exception when raise_exception then if sqlerrm='Scalar decision accepted' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','cccccccc-cccc-4ccc-8ccc-cccccccccccc',true);
 f:=public.review_dynamic_finding(p,fid,'{"version":1,"decision":"confirmed","note":"Reproduced the independent result","severity":"high","priority":"medium","confidence":"high"}');
 if f->>'version'<>'2' or f->>'verification'<>'confirmed' then raise exception 'Member decision missing';end if;
 if not exists(select 1 from public.dynamic_finding_events where finding_id=fid and payload->>'actorId'=auth.uid()::text) then raise exception 'Reviewer attribution missing';end if;
 begin perform public.review_dynamic_finding(p,fid,'{"version":1,"decision":"rejected","note":"Stale request"}');raise exception 'Stale version accepted';exception when raise_exception then if sqlerrm='Stale version accepted' then raise;end if;end;
 begin perform public.record_dynamic_remediation(p,fid,'{"version":2,"status":"resolved","note":"Trust the model"}');raise exception 'Resolution without regression accepted';exception when raise_exception then if sqlerrm='Resolution without regression accepted' then raise;end if;end;
 ret:=public.start_dynamic_regression_run(p,auth.uid(),(rev->>'id')::uuid,'finding-pass',rid);passed:=(ret->'run'->>'id')::uuid;perform public.claim_dynamic_run(p,passed,'worker',token,'finding-pass');perform public.transition_dynamic_run(p,passed,'running',jsonb_build_object('state','completed','verdict','passed','leaseToken',token,'checks',good,'evidence',ev));
 if (select payload->>'remediation' from public.dynamic_findings where id=fid)<>'open' then raise exception 'Pass automatically resolved finding';end if;
 if public.collect_dynamic_findings(p,passed)<>'[]'::jsonb then raise exception 'Passing candidate created';end if;
 f:=public.record_dynamic_remediation(p,fid,jsonb_build_object('version',2,'status','resolved','note','Inspected preserved failure and independent passing regression','regressionRunId',passed));
 if f->>'remediation'<>'resolved' then raise exception 'Valid resolution missing';end if;
 ret:=public.start_dynamic_regression_run(p,auth.uid(),(rev->>'id')::uuid,'finding-recurrence',rid);again:=(ret->'run'->>'id')::uuid;perform public.claim_dynamic_run(p,again,'worker',token,'finding-recurrence');perform public.transition_dynamic_run(p,again,'running',jsonb_build_object('state','completed','verdict','failed','leaseToken',token,'checks',failed,'evidence',ev));
 ret:=public.collect_dynamic_findings(p,again);if ret->0->>'id'<>fid::text or ret->0->>'observationCount'<>'2' or ret->0->>'remediation'<>'open' or ret->0->>'verification'<>'needs_investigation' then raise exception 'Recurrence not correlated and reopened';end if;
 if (select count(*) from public.dynamic_finding_events where finding_id=fid)<>3 then raise exception 'Decision history lost';end if;
 if (select payload from public.dynamic_runs where id=rid) is distinct from run then raise exception 'Original failed Run rewritten';end if;
 if jsonb_array_length(public.read_dynamic_finding(p,fid)->'observations')<>2 or jsonb_array_length(public.read_dynamic_finding(p,fid)->'events')<>3 then raise exception 'Snapshot detail missing history';end if;
 perform set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
 if exists(select 1 from public.dynamic_findings where id=fid) or exists(select 1 from public.dynamic_finding_events where finding_id=fid) or exists(select 1 from public.dynamic_finding_observations where finding_id=fid) then raise exception 'Non-member read';end if;
 begin perform public.collect_dynamic_findings(p,rid);raise exception 'Non-member collected';exception when insufficient_privilege then null;end;
 begin perform public.review_dynamic_finding(p,fid,'{"version":4,"decision":"rejected","note":"Unauthorized"}');raise exception 'Non-member decision';exception when insufficient_privilege then null;end;
 insert into finding_test_ids values(fid,rid);
 raise notice 'PASS: candidate evidence, idempotency, member attribution, stale guard, pinned resolution, recurrence, preserved Runs and RLS';
end $$;
reset role;
delete from public.project_members where project_id='11111111-1111-4111-8111-111111111111' and user_id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';
set local role authenticated;select set_config('request.jwt.claim.sub','cccccccc-cccc-4ccc-8ccc-cccccccccccc',true);
do $$declare fid uuid;rid uuid;begin select i.fid,i.rid into fid,rid from finding_test_ids i;
 if exists(select 1 from public.dynamic_findings where id=fid) then raise exception 'Revoked reader retained access';end if;
 begin perform public.read_dynamic_finding('11111111-1111-4111-8111-111111111111',fid);raise exception 'Revoked detail accepted';exception when insufficient_privilege then null;end;
 begin perform public.review_dynamic_finding('11111111-1111-4111-8111-111111111111',fid,'{"version":4,"decision":"rejected","note":"Revoked actor"}');raise exception 'Revoked review accepted';exception when insufficient_privilege then null;end;
 begin perform public.collect_dynamic_findings('11111111-1111-4111-8111-111111111111',rid);raise exception 'Revoked collection accepted';exception when insufficient_privilege then null;end;
 raise notice 'PASS: revoked member cannot read, collect or review';end $$;
rollback;
